@media (max-width: 760px) {
  .inventory-operation-card-transfer .inventory-operation-variant-filter {
    padding: 9px;
  }

  .inventory-operation-card-transfer .inventory-operation-variants-table-shell {
    max-height: none;
    overflow: visible;
    border: 0;
    background: transparent;
  }

  .inventory-operation-card-transfer .inventory-operation-variants-table {
    display: block;
    width: 100%;
    min-width: 0;
  }

  .inventory-operation-card-transfer .inventory-operation-variants-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  .inventory-operation-card-transfer .inventory-operation-variants-table tbody {
    display: grid;
    gap: 9px;
  }

  .inventory-operation-card-transfer .inventory-operation-variants-table tr {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 9px 12px;
    width: 100%;
    padding: 12px;
    border: 1px solid #e2e8f0;
    border-radius: 13px;
    background: #fff;
  }

  .inventory-operation-card-transfer .inventory-operation-variants-table td {
    display: grid;
    align-content: start;
    gap: 4px;
    width: auto !important;
    min-width: 0 !important;
    padding: 0;
    border: 0;
    white-space: normal;
  }

  .inventory-operation-card-transfer .inventory-operation-variants-table td:first-child {
    grid-column: 1 / -1;
    padding-bottom: 9px;
    border-bottom: 1px solid #edf2f7;
  }

  .inventory-operation-card-transfer .inventory-operation-variants-table td::before {
    color: #64748b;
    font-size: .69rem;
    font-weight: 800;
    line-height: 1.2;
  }

  .inventory-operation-card-transfer .inventory-operation-variants-table td:first-child::before { content: 'Позиция'; }
  .inventory-operation-card-transfer .inventory-operation-variants-table td:nth-child(2)::before { content: 'По системе'; }
  .inventory-operation-card-transfer .inventory-operation-variants-table td:nth-child(3)::before { content: 'Переместить'; }
  .inventory-operation-card-transfer .inventory-operation-variants-table td:nth-child(4)::before { content: 'После'; }

  .inventory-operation-card-transfer .inventory-operation-variants-table td.empty-state::before {
    content: none;
  }

  .inventory-operation-card-transfer .inventory-operation-quantity-cell input {
    width: 100%;
    min-width: 0;
    min-height: 44px;
    font-size: 16px;
  }

  .inventory-operation-card-transfer .inventory-operation-after-cell,
  .inventory-operation-card-transfer .inventory-transfer-observation {
    grid-column: 1 / -1;
  }

  .inventory-operation-card-transfer .inventory-transfer-after {
    white-space: normal;
    overflow-wrap: anywhere;
  }
}
